const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Upscaled atlas failed to load'));i.src=src;});
const exact=(cv)=>{let data=cv.getContext('2d',{willReadFrequently:true}).getImageData(0,0,cv.width,cv.height).data;for(let i=0;i<data.length;i+=4){const r=data[i],g=data[i+1],b=data[i+2],a=data[i+3];if(a!==255||!((r===0&&g===0&&b===0)||(r===255&&g===255&&b===255)||(r===255&&g===0&&b===0)))return false;}return true;};
function createText(tag,value){const el=document.createElement(tag);el.textContent=value;return el;}
async function mount(){
 if(document.getElementById('nls-resampled-v1610'))return;
 const anchor=document.getElementById('nerdeus-reference-elements-v169')||document.getElementById('nls-proof-lab-v164')||document.querySelector('.nls-workflow');
 if(!anchor)return;
 const details=document.createElement('details');details.id='nls-resampled-v1610';details.className='nls-resamp';
 details.open=new URLSearchParams(location.search).get('resampled')==='1';
 details.appendChild(createText('summary','Upscaled packaging elements · 540 × 215 food / 128 × 128 icons · candidate review'));
 const info=createText('p','Six food drawings and eight icon families were resampled at 300 DPI. This adds no missing original detail. All pixels are exact black, red, or white. Samples are NOT automatically used for real packages or print snapshots.');details.appendChild(info);
 const controls=document.createElement('div');controls.className='nls-resamp-control';
 controls.appendChild(createText('span','Compare enlargement method: '));
 const select=document.createElement('select');select.setAttribute('aria-label','Image resampling comparison');select.innerHTML='<option value="smooth">Lanczos + binary threshold (recommended)</option><option value="nearest">Nearest-neighbor (blocky comparison)</option>';controls.appendChild(select);details.appendChild(controls);
 const state=createText('p','Preparing pixel-exact candidate previews...');state.setAttribute('role','status');details.appendChild(state);
 const foodGrid=document.createElement('div');foodGrid.className='nls-resamp-food';details.appendChild(foodGrid);
 details.appendChild(createText('h3','Resampled icons (red and black variants)'));
 const iconGrid=document.createElement('div');iconGrid.className='nls-resamp-icons';details.appendChild(iconGrid);
 const disclaimer=createText('p','The finished loaf is unsuitable as dry baking mix product artwork. Printer and label-roll icons are for editor controls, not food labels. Do not copy flattened example dates, temperatures, QR codes, or allergen declarations.');details.appendChild(disclaimer);
 anchor.insertAdjacentElement('afterend',details);
 const style=document.createElement('style');style.id='nls-resamp-style';style.textContent='.nls-resamp{margin:13px 18px;padding:15px;border:1px solid #b3b9c1;border-left:5px solid #c52220;border-radius:10px;background:var(--surface,#fff);color:var(--ink,#122536);font:13px/1.5 system-ui,Arial,sans-serif}.nls-resamp summary{font-size:16px;font-weight:750;cursor:pointer}.nls-resamp-control{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:10px 0}.nls-resamp-control select{font:inherit;padding:8px;border-radius:6px;max-width:100%}.nls-resamp-food{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:12px}.nls-resamp-food article,.nls-resamp-icons article{background:#fff;color:#141414;padding:10px;border-radius:8px;border:1px solid #bbb}.nls-resamp-food canvas{width:100%;height:auto;image-rendering:pixelated;display:block;background:white}.nls-resamp-food strong,.nls-resamp-icons strong{display:block}.nls-resamp-food small,.nls-resamp-icons small{display:block;color:#555;font-size:11px}.nls-resamp-icons{display:grid;grid-template-columns:repeat(auto-fit,minmax(112px,1fr));gap:10px}.nls-resamp-icons canvas{display:block;width:100%;max-width:128px;height:auto;margin:auto;image-rendering:pixelated}@media(max-width:650px){.nls-resamp{margin:8px;padding:9px}.nls-resamp-food{grid-template-columns:repeat(2,minmax(0,1fr))}}';document.head.appendChild(style);
 let smooth,nearest,icons;
 try{[smooth,nearest,icons]=await Promise.all([load(SMOOTH_ATLAS),load(NEAREST_ATLAS),load(ICON_ATLAS)]);}catch(e){state.textContent='Candidate gallery unavailable: '+String(e.message||e);return;}
 const foodCards=[];
 for(const f of FOODS){
  const card=document.createElement('article');card.append(createText('strong',f.title));
  const cv=document.createElement('canvas');cv.width=540;cv.height=215;card.append(cv);
  card.append(createText('small','Original '+f.source.join(' × ')+' px → 540 × 215 px · 300 DPI · '+(f.printRole==='not-for-dry-mix'?'NOT FOR DRY MIX':'REVIEW ONLY')));
  foodGrid.append(card);foodCards.push({f,cv});
 }
 const rerender=()=>{
  const img=select.value==='nearest'?nearest:smooth;
  let approved=0;
  for(const {f,cv} of foodCards){const [sx,sy,sw,sh]=f.position,ctx=cv.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=false;ctx.drawImage(img,sx,sy,sw,sh,0,0,540,215);if(exact(cv))approved++;}
  state.textContent=approved+'/'+FOODS.length+' candidate previews verified for exact black/white pixels · '+select.options[select.selectedIndex].text+' · physical printing NOT verified.';
 };
 select.addEventListener('change',rerender);rerender();
 let iconOk=0;
 for(const icon of ICONS){const card=document.createElement('article');card.append(createText('strong',icon.label));
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=256;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=false;
 ctx.drawImage(icons,...icon.positionBlack,0,0,128,128);ctx.drawImage(icons,...icon.positionRed,0,128,128,128);
 if(exact(canvas))iconOk++;
 card.append(canvas,createText('small',icon.printRole==='editor-ui'?'Editor UI only':'Review candidate'));iconGrid.append(card);
 }
 state.textContent+=' · '+iconOk+'/'+ICONS.length+' icon pairs verified.';
}
window.NerdeusResampledElementsV1610={version:VERSION,foods:FOODS.map(x=>({id:x.id,source:x.source,target:[540,215],status:x.printRole})),icons:ICONS.map(x=>x.id),approvedForPrint:false,open:()=>{const e=document.getElementById('nls-resampled-v1610');if(e)e.open=true;}};
